// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring, Easing } from '../remotionShim';


export type SliderDragAnimationProps = Record<string, any>;

const SliderDragAnimation: React.FC<SliderDragAnimationProps> = ({
  backgroundColor = "#0c0d0e",
  transparentBackground = false,
  durationInSeconds = 8,
  startValue = 0.50,
  firstDragValue = 0.80,
  secondDragValue = 0.25,
  finalValue = 0.72,
  inactiveColor = "#232326",
  dotColor = "#ffffff",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Color/Background Parser safety
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Track Dimensions (fully visible from start to end with padding)
  const Y_center = height * 0.5;
  const padding = width * 0.1;
  const X_start = padding;
  const X_end = width - padding;
  const trackHeight = height * 0.055;
  const handleSize = height * 0.12;

  // Timing segments calculated dynamically based on total duration
  const totalFrames = durationInSeconds * fps;
  const tEnterEnd = Math.max(1, Math.floor(totalFrames * 0.12));
  const tClick = Math.max(tEnterEnd + 1, Math.floor(totalFrames * 0.18));
  const tDrag1 = Math.max(tClick + 1, Math.floor(totalFrames * 0.38));
  const tPause1 = Math.max(tDrag1 + 1, Math.floor(totalFrames * 0.44));
  const tDrag2 = Math.max(tPause1 + 1, Math.floor(totalFrames * 0.62));
  const tPause2 = Math.max(tDrag2 + 1, Math.floor(totalFrames * 0.68));
  const tDrag3 = Math.max(tPause2 + 1, Math.floor(totalFrames * 0.82));
  const tRelease = Math.max(tDrag3 + 1, Math.floor(totalFrames * 0.86));
  const tExitStart = Math.max(tRelease + 1, Math.floor(totalFrames * 0.90));
  const tExitEnd = Math.max(tExitStart + 1, Math.floor(totalFrames * 0.98));

  // Current slider value interpolation
  const sliderValue = interpolate(
    frame,
    [0, tClick, tDrag1, tPause1, tDrag2, tPause2, tDrag3, tRelease, totalFrames],
    [startValue, startValue, firstDragValue, firstDragValue, secondDragValue, secondDragValue, finalValue, finalValue, finalValue],
    {
      easing: Easing.inOut(Easing.quad),
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  // Dynamic hue based on slider value
  const currentHue = sliderValue * 360;
  const currentRGB = `hsl(${currentHue}, 100%, 50%)`;

  // Velocity calculation for mouse tilt
  const prevFrame = Math.max(0, frame - 1);
  const prevSliderValue = interpolate(
    prevFrame,
    [0, tClick, tDrag1, tPause1, tDrag2, tPause2, tDrag3, tRelease, totalFrames],
    [startValue, startValue, firstDragValue, firstDragValue, secondDragValue, secondDragValue, finalValue, finalValue, finalValue],
    {
      easing: Easing.inOut(Easing.quad),
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );
  
  const velocity = (sliderValue - prevSliderValue) * 12; // amplified for aesthetic tilt
  const cursorTilt = interpolate(velocity, [-5, 5], [-15, 15], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Calculate coordinates of the handle
  const X_handle = X_start + sliderValue * (X_end - X_start);

  // Mouse cursor targets the bottom-right region of the handle
  const cursorOffsetX = handleSize * 0.28;
  const cursorOffsetY = handleSize * 0.35;

  // Interpolated mouse positions
  let mouseX = 0;
  let mouseY = 0;

  if (frame < tEnterEnd) {
    const progress = interpolate(frame, [0, tEnterEnd], [0, 1], {
      easing: Easing.bezier(0.25, 0.1, 0.25, 1),
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    });
    const X_handle_start = X_start + startValue * (X_end - X_start);
    mouseX = interpolate(progress, [0, 1], [width * 0.85, X_handle_start + cursorOffsetX]);
    mouseY = interpolate(progress, [0, 1], [height * 0.85, Y_center + cursorOffsetY]);
  } else if (frame < tExitStart) {
    mouseX = X_handle + cursorOffsetX;
    mouseY = Y_center + cursorOffsetY;
  } else {
    const progress = interpolate(frame, [tExitStart, tExitEnd], [0, 1], {
      easing: Easing.bezier(0.25, 0.1, 0.25, 1),
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    });
    const X_handle_final = X_start + finalValue * (X_end - X_start);
    mouseX = interpolate(progress, [0, 1], [X_handle_final + cursorOffsetX, width * 0.85]);
    mouseY = interpolate(progress, [0, 1], [Y_center + cursorOffsetY, height * 0.85]);
  }

  // Fade out cursor at the end
  const mouseOpacity = interpolate(frame, [tExitStart, tExitEnd], [1, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Tactile mouse click scaling effect
  const mouseScale = interpolate(
    frame,
    [0, tClick, tClick + 3, tRelease, tRelease + 3, totalFrames],
    [1, 1, 0.82, 0.82, 1, 1],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  // Click & Release Ripples
  const clickRippleProgress = (frame - tClick) / 18;
  const clickRippleVisible = clickRippleProgress >= 0 && clickRippleProgress <= 1;
  const clickRippleScale = interpolate(clickRippleProgress, [0, 1], [0.1, 2.5], { extrapolateRight: "clamp" });
  const clickRippleOpacity = interpolate(clickRippleProgress, [0, 1], [0.7, 0], { extrapolateRight: "clamp" });

  const releaseRippleProgress = (frame - tRelease) / 18;
  const releaseRippleVisible = releaseRippleProgress >= 0 && releaseRippleProgress <= 1;
  const releaseRippleScale = interpolate(releaseRippleProgress, [0, 1], [0.1, 2.5], { extrapolateRight: "clamp" });
  const releaseRippleOpacity = interpolate(releaseRippleProgress, [0, 1], [0.7, 0], { extrapolateRight: "clamp" });

  // Generate 32 evenly spaced track background dots (relative to the track container)
  const totalDots = 32;
  const dots = Array.from({ length: totalDots }).map((_, i) => {
    const dotX = (i / (totalDots - 1)) * (X_end - X_start);
    const absoluteDotX = X_start + dotX;
    const isInsideActiveTrack = absoluteDotX < X_handle;
    return { x: dotX, active: isInsideActiveTrack };
  });

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        backgroundImage: transparentBackground
          ? "none"
          : `radial-gradient(circle at 50% 50%, #16171d 0%, #060608 100%)`,
        display: "flex",
        flexDirection: "column",
        justifyContent: "center",
        alignItems: "center",
        overflow: "hidden",
      }}
    >
      {/* SLIDER CONTAINER */}
      <div
        style={{
          position: "absolute",
          top: Y_center - trackHeight / 2,
          left: X_start,
          width: X_end - X_start,
          height: trackHeight,
          backgroundColor: inactiveColor,
          borderRadius: trackHeight / 2,
          boxShadow: "inset 0 4px 12px rgba(0, 0, 0, 0.6)",
          overflow: "hidden",
          zIndex: 1,
          transition: "none",
        }}
      >
        {/* ACTIVE HUE GRADIENT FILL (DRAG LINE RGB) */}
        <div
          style={{
            position: "absolute",
            left: 0,
            top: 0,
            width: X_handle - X_start,
            height: "100%",
            background: "linear-gradient(to right, #ff0000, #ffff00, #00ff00, #00ffff, #0000ff, #ff00ff, #ff0000)",
            backgroundSize: `${X_end - X_start}px 100%`,
            backgroundPosition: "left center",
            backgroundRepeat: "no-repeat",
            boxShadow: `0 0 25px ${currentRGB}33`,
            transition: "none",
          }}
        />

        {/* DOTS PATH */}
        {dots.map((dot, idx) => {
          const opacityVal = dot.active ? 0.0 : 0.35;
          return (
            <div
              key={idx}
              style={{
                position: "absolute",
                left: dot.x,
                top: "50%",
                width: Math.min(width, height) * 0.007,
                height: Math.min(width, height) * 0.007,
                borderRadius: "50%",
                backgroundColor: dotColor,
                opacity: opacityVal,
                transform: "translate(-50%, -50%)",
                transition: "none",
              }}
            />
          );
        })}
      </div>

      {/* ROUNDED WHITE HANDLE / THUMB */}
      <div
        style={{
          position: "absolute",
          left: X_handle,
          top: Y_center,
          width: handleSize,
          height: handleSize,
          backgroundColor: "#ffffff",
          borderRadius: "50%",
          transform: "translate(-50%, -50%)",
          boxShadow: `0 12px 28px rgba(0,0,0,0.5), 0 0 30px ${currentRGB}66, inset 0 2px 4px rgba(255,255,255,0.4)`,
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          zIndex: 3,
          transition: "none",
        }}
      />

      {/* RIPPLE EFFECT ANCHORS */}
      {clickRippleVisible && (
        <div
          style={{
            position: "absolute",
            left: mouseX,
            top: mouseY,
            width: 40,
            height: 40,
            border: `3px solid ${currentRGB}`,
            borderRadius: "50%",
            transform: `translate(-50%, -50%) scale(${clickRippleScale})`,
            opacity: clickRippleOpacity,
            pointerEvents: "none",
            zIndex: 8,
            transition: "none",
          }}
        />
      )}

      {releaseRippleVisible && (
        <div
          style={{
            position: "absolute",
            left: mouseX,
            top: mouseY,
            width: 40,
            height: 40,
            border: `3px solid ${currentRGB}`,
            borderRadius: "50%",
            transform: `translate(-50%, -50%) scale(${releaseRippleScale})`,
            opacity: releaseRippleOpacity,
            pointerEvents: "none",
            zIndex: 8,
            transition: "none",
          }}
        />
      )}

      {/* MOUSE CURSOR */}
      <div
        style={{
          position: "absolute",
          left: mouseX - 2,
          top: mouseY - 2,
          transform: `scale(${mouseScale}) rotate(${cursorTilt}deg)`,
          transformOrigin: "2px 2px",
          opacity: mouseOpacity,
          filter: "drop-shadow(0px 8px 16px rgba(0, 0, 0, 0.45))",
          zIndex: 9,
          pointerEvents: "none",
          transition: "none",
        }}
      >
        <svg
          width={Math.min(width, height) * 0.07}
          height={Math.min(width, height) * 0.07}
          viewBox="0 0 32 32"
          style={{ overflow: "visible" }}
        >
          <path
            d="M2,2 L14,26 L19.5,15.5 L30,14 Z"
            fill="#121214"
            stroke="white"
            strokeWidth="2.8"
            strokeLinejoin="round"
          />
        </svg>
      </div>
    </AbsoluteFill>
  );
};

export default SliderDragAnimation;